    T = np.array(c['cam2world_gl'])
    dep = np.asarray(obs.depth[cam])
    if dep.ndim == 3: dep=dep[-1]
    z = float(dep[int(v),int(u)]) if depth is None else depth
    cv = np.linalg.solve(K, np.array([u,v,1.]))*z
    return T[:3,3]+T[:3,:3] @ (cv*np.array([1,-1,-1]))

